-- German (deDE): the guide forever/class/warlock/incubus-horde (forever/class/warlock/incubus-horde.guide).
-- Written by `forge i18n guides sync deDE`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in German (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in German words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Succubus and Incubus (Horde)"] = "Sukkubus und Inkubus (Horde)",
	["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "Auf Stufe 20: der Sukkubus und der Inkubus von Forever, sein männliches Gegenstück, jeweils mit einem Seelenbeutel für deine Splitter.",

	-- Step 1: Devourer of Souls (Orgrimmar)
	-- {npc:5875} Gan'rul Bloodeye · {object:172960} Cleft of Shadow · {object:172982} Valley of Strength · {npc:5909} Cazul · {npc:5675} Carendin Halgar · {zone:1458} Undercity · {quest:1472} Devourer of Souls · {zone:1454} Orgrimmar
	["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "Mit Stufe 20 schickt dich {npc:5875} im {object:172960} unter {object:172982} zu {npc:5909} ein paar Schritte weiter. Zwei Lehrer starten diese Dämonen, {npc:5875} hier und {npc:5675} in {zone:1458}, und du kannst nur einen nehmen; dieser Guide folgt der Quest {quest:1472}, die du genommen hast. {npc:5909} bietet beide Zweige von {zone:1454} an: Nimm beide.",
	["the succubus"] = "der Sukkubus",
	["the incubus"] = "der Inkubus",

	-- Step 2: Zankaja
	-- {npc:5910} Zankaja · {object:172982} Valley of Strength
	["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910} lebt in einer Hütte auf den Klippen an der Westseite der Stadt, über {object:172982}: Steig den Windreiterturm hinauf, überquere oben die Brücke nach Westen und biege dahinter rechts ab. Sie schickt dich zu den Crossroads.",

	-- Step 3: Magar
	-- {npc:3363} Magar · {object:173018} Magar's Cloth Goods · {object:172960} Cleft of Shadow · {zone:1440} Ashenvale
	["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} führt {object:173018} an der Hauptstraße östlich von {object:172960}. Er bittet dich, seine Gefährtin Krilge in {zone:1440} zu suchen.",

	-- Step 4: Gazrog
	-- {npc:3464} Gazrog · {npc:4197} Ken'zigla · {area:2539} Malaka'jin · {zone:1442} Stonetalon Mountains
	["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} wartet vor dem Gasthaus an den Crossroads. Er schickt dich weiter zu {npc:4197} in {area:2539}, in {zone:1442}.",

	-- Step 5: Ken'zigla
	-- {zone:1442} Stonetalon Mountains · {area:2539} Malaka'jin · {npc:4197} Ken'zigla · {npc:5911} Grunt Logmar
	["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Nimm die Straße von den Crossroads nach Westen in {zone:1442} und, kurz hinter der Grenze, den schwachen Pfad nach links (Süden) hinauf: {area:2539} ist von der Hauptstraße aus nicht erreichbar. {npc:4197} gibt dir ihren Trank für {npc:5911}.",

	-- Step 6: Grunt Dogran
	-- {npc:5911} Grunt Logmar · {area:378} Camp Taurajo · {npc:5875} Gan'rul Bloodeye
	["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911} steht bei {area:378}, südlich der Crossroads die Straße hinunter. Er schickt dich nach Norden zum Stacheleber-Lager, wo Dogran gefangen gehalten wird: das Lager mit zwei nebeneinander stehenden Hütten, nordwestlich eines Täuschungslagers, dessen Hütten getrennt stehen. Ein seltener Stacheleber der Stufe 22 (Elite) bewacht manchmal die Hütten: Schick deinen Leerwandler hinein, opfere ihn notfalls, und sprich mit Dogran. Er gibt dir einen Anhänger für {npc:5875}. Behalte ihn.",

	-- Step 7: The Binding: succubus (Orgrimmar)
	-- {quest:1513} The Binding · {zone:1454} Orgrimmar
	["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: Sukkubus ({zone:1454})",
	-- {npc:5875} Gan'rul Bloodeye · {item:6626} Dogran's Pendant · {object:172960} Cleft of Shadow · {npc:3216} Neeru Fireblade
	["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "Zurück zu {npc:5875} mit dem Anhänger. Er gibt dir {item:6626}: Bring ihn über {object:172960} zum Zelt von {npc:3216}, stell dich auf den violetten Kreis und benutze ihn. Beschwöre zuerst deinen Leerwandler und lass ihn tanken: Der Sukkubus (Stufe 20, kein Elite) bezaubert und peitscht; halte deinen Schaden über Zeit auf ihm. Gewinnt er, benutze den Anhänger erneut. Behalte den Anhänger: {npc:5875} nimmt ihn zurück.",
	-- {item:6626} Dogran's Pendant
	["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}, auf dem Kreis in Neerus Zelt",

	-- Step 8: Fallen Sky Lake
	-- {area:422} Fallen Sky Lake · {zone:1440} Ashenvale · {area:431} Splintertree Post · {item:190232} Withered Scarf · {npc:3931} Shadethicket Oracle
	-- plural, as words: Shadethicket Stone Movers = {npc:3782} Shadethicket Stone Mover
	["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-26) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so come at 25 or later (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} liegt im südlichen {zone:1440}, südwestlich von {area:431}. Die Shadethicket Stone Movers und Bark Rippers (Stufe 25-26) rund um den See lassen {item:190232} bei etwa jedem zwanzigsten Kill fallen, und der einzelne {npc:3931} (30) kann es auch fallen lassen: Plane eine gute Zahl an Kills ein, komm also mit 25 oder später (Forever hat diese Quest auf Stufe 27 gesetzt); ist der Sukkubus bereits gebunden, kannst du sie dir für dein Leveln in {zone:1440} in deinen Zwanzigern aufheben. Sie respawnen in fünf Minuten.",

	-- Step 9: The Binding: incubus (Orgrimmar)
	-- {quest:65604} The Binding · {zone:1454} Orgrimmar
	["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}: Inkubus ({zone:1454})",
	-- {npc:5875} Gan'rul Bloodeye · {item:190232} Withered Scarf
	["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "Zurück zu {npc:5875} mit dem Schal, benutze dann {item:190232} auf demselben Kreis in Neerus Zelt und besiege den Inkubus, den er ruft (Stufe 20, kein Elite), während dein Leerwandler tankt. Behalte den Schal: {npc:5875} nimmt ihn zurück.",
	-- {npc:185335} Summoned Incubus
	["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}, am Kreis in Neerus Zelt",

	-- Step 10: Devourer of Souls (Undercity)
	-- {object:1661} The Undercity · {npc:5675} Carendin Halgar · {quest:1472} Devourer of Souls · {npc:5875} Gan'rul Bloodeye · {object:36082} Magic Quarter · {npc:5693} Godrick Farsan
	["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "Die Version von {object:1661}, für Hexenmeister, die {quest:1472} von {npc:5675} statt der von {npc:5875} genommen haben. Mit Stufe 20 schickt dich {npc:5675} im {object:36082} zu {npc:5693} in der Nähe. {npc:5693} zeigt dir ein Bild jeder Beute und bietet beide Zweige an: Nimm beide.",

	-- Step 11: Silverpine hearts
	["Silverpine hearts"] = "Herzen aus Silberwald",
	-- {npc:185333} Avelina Lilly · {area:279} Dalaran · {area:233} Ambermill · {npc:5682} Dalin Forgewright · {area:230} Greymane Wall
	["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333} (Stufe 22) arbeitet als Schneiderin für die Magier von {area:279} in {area:233}, im östlichen Silberwald: Die Magier um sie herum sind feindlich. {npc:5682} (Stufe 20, kein Elite) patrouilliert nahe {area:230} im äußersten Süden. Beide sind allianzfreundliche Menschen: Sie anzugreifen kann dich für PvP markieren. Jeder lässt sein Herz fallen.",

	-- Step 12: Corma Villard
	-- {npc:5683} Corma Villard · {zone:1437} Wetlands · {area:881} Thandol Span · {zone:1458} Undercity · {area:287} Hillsbrad · {zone:1417} Arathi Highlands
	["{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "{npc:5683} (Stufe 22, kein Elite; in älteren Daten Comar) wandert im Norden der {zone:1437} direkt hinter {area:881}, rechts, wenn du von der Brücke kommst. Geh von {zone:1458} aus durch {area:287} und {zone:1417}, wo die Mobs Stufe 30 und höher haben. Sie anzugreifen markiert dich für PvP.",

	-- Step 13: The Binding: succubus (Undercity)
	-- {quest:1474} The Binding · {zone:1458} Undercity
	["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}: Sukkubus ({zone:1458})",
	-- {npc:5675} Carendin Halgar · {npc:5683} Corma Villard · {item:6286} Pure Hearts
	["Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "Zurück zu {npc:5675} mit Dalins und {npc:5683}s Herzen. Er gibt dir {item:6286}: Geh zum Beschwörungskreis unter ihm hinunter, stell dich darauf und benutze sie. Beschwöre zuerst deinen Leerwandler und halte den Kampf auf dem Kreis, sonst töten ihn vielleicht die Wachen und der Kill zählt nicht. Gewinnt er, benutze die Herzen erneut; behalte sie, {npc:5675} nimmt sie zurück.",
	-- {item:6286} Pure Hearts · {npc:5675} Carendin Halgar
	["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}, auf dem Kreis unter {npc:5675}",

	-- Step 14: Isaac Pearson
	-- {npc:185334} Isaac Pearson · {area:392} Ratchet · {zone:1413} Barrens · {zone:1411} Durotar · {zone:1454} Orgrimmar
	["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334} (Stufe 22) arbeitet in {area:392}, an der Küste des {zone:1413}, an einer von zwei Stellen in der Stadt: Nimm das Luftschiff nach {zone:1411} und geh nach Süden, oder flieg von {zone:1454} aus. Er ist ein allianzfreundlicher Mensch: Ihn anzugreifen kann dich für PvP markieren.",

	-- Step 15: The Binding: incubus (Undercity)
	-- {quest:65597} The Binding · {zone:1458} Undercity
	["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}: Inkubus ({zone:1458})",
	-- {npc:5675} Carendin Halgar · {item:190181} Lovers' Hearts
	["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "Zurück zu {npc:5675} mit den Herzen der Liebenden, platziere dann {item:190181} auf demselben Kreis und besiege den Inkubus, den sie rufen (Stufe 20, kein Elite; er kann dich bezaubern). Behalte die Herzen: {npc:5675} nimmt sie zurück.",
	-- {npc:185335} Summoned Incubus · {npc:5675} Carendin Halgar
	["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}, am Kreis unter {npc:5675}",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["A second seducer demon, the male sayaad, and a soul shard bag to carry your shards."] = "Ein zweiter Verführungsdämon, der männliche Sayaad, und eine Seelensplittertasche für deine Splitter.",
	-- ["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers offer the incubus, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one: this guide follows whichever {quest:1472} you took."] = "Mit 20 schickt dich {npc:5875} in {object:172960} unter {object:172982} zu {npc:5909} ein paar Schritte weiter. Zwei Lehrer bieten den Inkubus an, {npc:5875} hier und {npc:5675} in {zone:1458}, und du kannst nur einen nehmen: Dieser Guide folgt der Quest {quest:1472}, die du angenommen hast.",
	-- ["Back to {npc:5675} in the {object:36082}. Place the hearts at the summoning circle below him and defeat the incubus they call."] = "Zurück zu {npc:5675} in {object:36082}. Leg die Herzen am Beschwörungskreis unter ihm ab und besiege den Inkubus, den sie rufen.",
	-- ["Back to {npc:5875} in the {object:172960}. Take the scarf to the summoning circle in {npc:3216}'s tent nearby and defeat the incubus it calls."] = "Zurück zu {npc:5875} in {object:172960}. Bring den Schal zum Beschwörungskreis im Zelt von {npc:3216} in der Nähe und besiege den Inkubus, den er ruft.",
	-- ["Incubus (Horde)"] = "Inkubus (Horde)",
	-- ["{area:422} lies in southern {zone:1440}, south of {area:431}. The Shadethicket bog beasts around the lake drop the {item:190232}, about one in twenty."] = "{area:422} liegt im Süden von {zone:1440}, südlich von {area:431}. Die Sumpfbestien des Schattendickichts rund um den See lassen {item:190232} fallen, etwa eine von zwanzig.",
	-- ["{npc:185333} works as a tailor for the {area:279} wizards at {area:233}, in eastern {zone:1421}. Take her heart."] = "{npc:185333} arbeitet als Schneiderin für die Magier von {area:279} in {area:233}, im Osten von {zone:1421}. Nimm ihr Herz.",
	-- ["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and ride or fly on to {area:392}."] = "{npc:185334} arbeitet in {area:392}, an der Küste von {zone:1413}. Nimm den Zeppelin nach {zone:1411} und reite oder flieg weiter nach {area:392}.",
	-- ["{npc:185334} works in {area:392}, on the {zone:1413} coast. Take the zeppelin to {zone:1411} and walk or fly on to {area:392}."] = "{npc:185334} arbeitet in {area:392} an der Küste von {zone:1413}. Nimm den Zeppelin nach {zone:1411} und geh oder flieg weiter nach {area:392}.",
	-- ["{npc:3363} keeps {object:173018}, east of the {object:172960} along the main street. He asks you to look for his mate, Krilge."] = "{npc:3363} führt {object:173018}, östlich von {object:172960} an der Hauptstraße. Er bittet dich, nach seiner Gefährtin Krilge zu suchen.",
	-- ["{npc:5675}: he binds the incubus to you"] = "{npc:5675}: Er bindet den Inkubus an dich",
	-- ["{npc:5875}: he binds the incubus to you"] = "{npc:5875}: Er bindet den Inkubus an dich",
	-- ["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} in the Temple of the Damned, just north of him."] = "Die Version von {object:1661}, für Hexenmeister, die {quest:1472} bei {npc:5675} statt bei {npc:5875} angenommen haben. Mit 20 schickt dich {npc:5675} in {object:36082} zu {npc:5693} im Tempel der Verdammten, direkt nördlich von ihm.",
